const SAT_MAP_URI = "data:image/jpeg;base64,";
function projX(lon){ return (lon+180)/360*MAP_W; }
function projY(lat){ return (90-lat)/180*MAP_H; }
function getDistance(from, to) {
  const cf=CITIES[from], ct=CITIES[to];
  if(!cf||!ct) return 1000;
  const R=3959, toR=Math.PI/180;
  const dLat=(ct.lat-cf.lat)*toR, dLon=(ct.lon-cf.lon)*toR;
  const a=Math.sin(dLat/2)**2 + Math.cos(cf.lat*toR)*Math.cos(ct.lat*toR)*Math.sin(dLon/2)**2;
  return Math.round(R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)));
}
function renderRegionTabs() {
  const el = document.getElementById('region-tabs');
  el.innerHTML = REGIONS.map(r =>
    `<div class="region-tab ${r===STATE.viewRegion?'active':''}" onclick="setRegion('${r}')">${r}</div>`
  ).join('') + `<div class="region-tab ${STATE.viewRegion==='ALL'?'active':''}" onclick="setRegion('ALL')">WORLD</div>`;
}
function setRegion(r){
  STATE.viewRegion = r;
  renderRegionTabs();
  if (r === 'ALL') {
    STATE.mapZoom = ZOOM_MIN;                          // zoom out to world view
    centerOnXY(CITIES[STATE.homeBase].x, 454);         // 454 ≈ inhabited vertical midpoint
  } else {
    STATE.mapZoom = 1.75;                              // zoom in to the region
    centerOnRegion(r);                                 // frame that region's cities
  }
  renderMap();
}
function centerOnRegion(region){
  const cs = Object.values(CITIES).filter(c=>c.region===region);
  if(!cs.length) return;
  const ax = cs.reduce((s,c)=>s+c.x,0)/cs.length;
  const ay = cs.reduce((s,c)=>s+c.y,0)/cs.length;
  centerOnXY(ax, ay);
}
function centerOnXY(x,y){
  const z = STATE.mapZoom || 1;
  STATE.mapTX = VIEW_W/2 - x*z;
  STATE.mapTY = VIEW_H/2 - y*z;
}
function centerOnCity(name){ const c=CITIES[name]; if(c) centerOnXY(c.x,c.y); }
function newsGoTo(city, region, weather){
  try {
    if (city && CITIES[city]) {
      STATE.viewRegion = CITIES[city].region;
      renderRegionTabs();
      // Weather alerts lean in 15% toward the storm (click again to push closer);
      // other news snaps to a close city view.
      STATE.mapZoom = weather
        ? Math.min(ZOOM_MAX, (STATE.mapZoom || 1) * 1.15)
        : 2.4;
      centerOnCity(city);
      renderMap(); applyPan();
    } else if (region) {
      setRegion(region);             // frame the whole region
    }
  } catch(e){}
}
const ZOOM_MIN = 0.65, ZOOM_MAX = 6;   // capped: satellite raster pixelates beyond ~6x
function applyPan(){
  const z = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, STATE.mapZoom || 1));
  STATE.mapZoom = z;
  // Clamp/wrap for DISPLAY only — keep STATE.mapTX/TY as the true logical position so that
  // zooming out and back in returns you to exactly the same place.
  const period = MAP_W * z;
  let t = STATE.mapTX % period; if(t>0) t-=period;                      // wrap horizontally
  const dispTY = Math.max(VIEW_H - MAP_H*z, Math.min(0, STATE.mapTY));  // clamp at poles
  const zp = document.getElementById('zoom-pct');
  if (zp) zp.textContent = Math.round(z * 100) + '%';
  const g=document.getElementById('pan');
  if(!g){ requestAnimationFrame(applyPan); return; }  // retry after paint if DOM not ready
  g.setAttribute('transform',`translate(${t.toFixed(2)},${dispTY.toFixed(2)}) scale(${z})`);

  const inv = 1/z;
  const marks = document.querySelectorAll('#pan .cmark');
  for(let i=0;i<marks.length;i++) marks[i].setAttribute('transform', `scale(${inv})`);
}
let _cityClickTimer = null;
function onCityClick(e, name) {
  if (_mapDragged) return;
  e.stopPropagation();
  const sx = e.clientX, sy = e.clientY;
  if (e.detail >= 2 || _cityClickTimer) {   // double-click → city info & improvements
    clearTimeout(_cityClickTimer);
    _cityClickTimer = null;
    openCityModal(name);
    return;
  }
  _cityClickTimer = setTimeout(() => {
    _cityClickTimer = null;
    handleCitySingleClick(name, sx, sy);
  }, 300);
}
function handleCitySingleClick(name, sx, sy) {
  if (STATE.routeFrom && STATE.routeFrom !== name) {
    openRouteCreation(STATE.routeFrom, name);
    STATE.routeFrom = null; STATE.selectedCity = null;
    hideCityPanel();
    renderMap();
  } else {
    STATE.selectedCity = name; STATE.routeFrom = name;
    showCityPanel(name, sx, sy);
    renderMap();
  }
}
function showCityPanel(name, screenX, screenY) {
  // No popup — just show a brief flash indicating the city is selected as route origin
  const c = CITIES[name];
  const myRoutes = STATE.routes.filter(r=>r.from===name||r.to===name).length;
  const routeNote = myRoutes ? ` · ${myRoutes} route${myRoutes>1?'s':''}` : '';
  if (STATE.routeFrom && STATE.routeFrom !== name) {
    showFlash(`✈ Select destination city for route from ${STATE.routeFrom}`);
  } else {
    showFlash(`📍 ${name} selected — click another city to open a route${routeNote}`);
  }
}
function hideCityPanel() {}
// ── On-map route hover card (uses uk-info / uk-badge from the UI kit) ──────
let _ukHoverCity = null;
function _ukDemandProxy(c){ // 0..100 legible demand proxy from city fundamentals
  if(!c) return 0;
  const v = (c.econ||0)*0.5 + (c.tourism||0)*0.35 + Math.min(100,(c.pop||0)*8)*0.15;
  return Math.max(1, Math.min(100, Math.round(v)));
}
function _ukRivalsOnPair(from,to){
  return (STATE.competitors||[]).filter(comp=>(comp.routeList||[]).some(r=>
    (r.from===from&&r.to===to)||(r.from===to&&r.to===from))).length;
}
function buildHoverCard(name){
  const c = CITIES[name]; if(!c) return '';
  const from = STATE.routeFrom && STATE.routeFrom!==name ? STATE.routeFrom : null;
  // existing route to this city (from a hub or selected origin)
  const existing = STATE.routes.find(r=> (from? ((r.from===from&&r.to===name)||(r.from===name&&r.to===from))
                                               : (r.from===name||r.to===name)) );
  const dem = _ukDemandProxy(c);
  const demCls = dem>=70?'hi':dem>=45?'warn':'lo';
  if(from){
    // route-pair preview: from -> hovered city
    const dist = Math.round(getDistance(from,name));
    const rivals = _ukRivalsOnPair(from,name);
    const compTxt = rivals>=3?'High':rivals>=1?'Medium':'Low';
    const compCls = rivals>=3?'lo':rivals>=1?'warn':'hi';
    let statusBadge = existing
      ? ((existing.profit||0)>=0?'<span class="uk-badge uk-badge--profit">Profitable</span>':'<span class="uk-badge uk-badge--risk">At Risk</span>')
      : (rivals>=1?'<span class="uk-badge uk-badge--contested">Contested</span>':'<span class="uk-badge uk-badge--new">New Route</span>');
    const profLine = existing
      ? `<div class="uk-info-cell"><div class="uk-k">Profit / mo</div><div class="uk-v ${(existing.profit||0)>=0?'hi':'lo'}">${(existing.profit||0)>=0?'+':''}$${(existing.profit||0).toFixed(1)}M</div></div>`
      : `<div class="uk-info-cell"><div class="uk-k">Frequency</div><div class="uk-v">Potential</div></div>`;
    const open1 = _ukCardOpen();
    return `<div class="uk-info-head"><span class="uk-info-pair">${CITIES[from]?.abbr||from} <span class="uk-arrow">→</span> ${c.abbr}</span>${statusBadge}<span class="uk-hc-ctl"><span class="uk-hc-chev ${open1?'':'closed'}" data-hc="chev" title="${open1?'Collapse':'Expand'}">⌄</span><span class="uk-hc-x" data-hc="x" title="Close">✕</span></span></div>
      ${open1?`<div class="uk-info-grid">
        <div class="uk-info-cell"><div class="uk-k">Demand</div><div class="uk-v ${demCls}">${dem}</div><div class="uk-meter"><i style="width:${dem}%"></i></div></div>
        <div class="uk-info-cell"><div class="uk-k">Competition</div><div class="uk-v ${compCls}">${compTxt}</div></div>
        ${profLine}
        <div class="uk-info-cell"><div class="uk-k">Distance</div><div class="uk-v">${dist.toLocaleString()} mi</div></div>
      </div>
      <div style="font-size:10.7px;color:var(--muted2);margin-top:9px;text-align:center">Click to open route ${CITIES[from]?.abbr||from}→${c.abbr}</div>`:''}`;
  }
  // standalone city card
  const myR = STATE.routes.filter(r=>r.from===name||r.to===name).length;
  const isHub = (STATE.hubs||[]).includes(name);
  const badge = isHub?'<span class="uk-badge uk-badge--stable">Your Hub</span>':myR?'<span class="uk-badge uk-badge--profit">Served</span>':'<span class="uk-badge uk-badge--muted">Unserved</span>';
  const open2 = _ukCardOpen();
  return `<div class="uk-info-head"><span class="uk-info-pair">${c.abbr} <span style="color:var(--muted2);font-weight:500;font-size:13.6px;margin-left:6px">${name}</span></span>${badge}<span class="uk-hc-ctl"><span class="uk-hc-chev ${open2?'':'closed'}" data-hc="chev" title="${open2?'Collapse':'Expand'}">⌄</span><span class="uk-hc-x" data-hc="x" title="Close">✕</span></span></div>
    ${open2?`<div class="uk-info-grid">
      <div class="uk-info-cell"><div class="uk-k">Demand</div><div class="uk-v ${demCls}">${dem}</div><div class="uk-meter"><i style="width:${dem}%"></i></div></div>
      <div class="uk-info-cell"><div class="uk-k">Region</div><div class="uk-v" style="font-size:13.6px">${c.region}</div></div>
      <div class="uk-info-cell"><div class="uk-k">Your Routes</div><div class="uk-v">${myR}</div></div>
      <div class="uk-info-cell"><div class="uk-k">Airport</div><div class="uk-v">Lv ${c.level||3}</div></div>
    </div>
    <div style="font-size:10.7px;color:var(--muted2);margin-top:9px;text-align:center">Click to select as route origin</div>`:''}`;
}
function showHoverCard(name, clientX, clientY){
  const card=document.getElementById('uk-hovercard'); const cont=document.getElementById('map-container');
  if(!card||!cont) return;
  const html=buildHoverCard(name); if(!html){ card.style.display='none'; return; }
  card.innerHTML=html; card.style.display='block';
  const cr=cont.getBoundingClientRect();
  let x=clientX-cr.left+16, y=clientY-cr.top+16;
  // keep inside the container
  const cw=card.offsetWidth||248, ch=card.offsetHeight||140;
  if(x+cw>cr.width-8) x=clientX-cr.left-cw-16;
  if(y+ch>cr.height-8) y=cr.height-ch-8;
  if(y<8) y=8;
  card.style.left=x+'px'; card.style.top=y+'px';
}
function hideHoverCard(){ const card=document.getElementById('uk-hovercard'); if(card) card.style.display='none'; _ukHoverCity=null; }
function _ukCardOpen(){ try { return localStorage.getItem('aeHoverCardOpen') === '1'; } catch(e) { return false; } }
function _ukToggleCardOpen(){
  try { localStorage.setItem('aeHoverCardOpen', _ukCardOpen() ? '0' : '1'); } catch(e) {}
  // re-render in place at the current position
  const card=document.getElementById('uk-hovercard');
  if (card && _ukHoverCity) { const html=buildHoverCard(_ukHoverCity); if(html) card.innerHTML=html; }
}
function _ukInitMapHover(){
  const cont=document.getElementById('map-container'); if(!cont||cont._ukHoverBound) return;
  cont._ukHoverBound=true;
  const card=document.getElementById('uk-hovercard');
  // card controls: chevron toggles, ✕ closes, clicking the body closes too
  if (card && !card._ukBound) {
    card._ukBound = true;
    card.addEventListener('click', e=>{
      const ctl = e.target.closest && e.target.closest('[data-hc]');
      e.stopPropagation();
      if (ctl && ctl.getAttribute('data-hc')==='chev') { _ukToggleCardOpen(); return; }
      hideHoverCard();   // ✕ or any click on the card body
    });
    card.addEventListener('mouseleave', ()=>hideHoverCard());
  }
  cont.addEventListener('mouseover', e=>{
    const g=e.target.closest && e.target.closest('.city-dot'); if(!g) return;
    const name=g.getAttribute('data-city'); if(!name) return;
    _ukHoverCity=name; showHoverCard(name, e.clientX, e.clientY);
  });
  cont.addEventListener('mousemove', e=>{
    if(!_ukHoverCity) return;
    if (e.target.closest && e.target.closest('#uk-hovercard')) return;         // resting on the card keeps it open
    const g = e.target.closest && e.target.closest('.city-dot');
    if (!g) { hideHoverCard(); return; }                                       // off the dot → hide promptly
    const name = g.getAttribute('data-city');
    if (name && name !== _ukHoverCity) { _ukHoverCity = name; }
    showHoverCard(_ukHoverCity, e.clientX, e.clientY);
  });
  cont.addEventListener('mousedown', e=>{                                      // pan/zoom/click never strands the card
    if (e.target.closest && e.target.closest('#uk-hovercard')) return;
    hideHoverCard();
  }, true);
  cont.addEventListener('mouseleave', ()=>hideHoverCard());
}
