function arenaNameOptions(sport){
  const co = (STATE.coName || 'SKYLINE');
  const v = sport.venue;
  return [
    { label:'Classic',  name:`${co} ${v}`,             costMult:1.0,  demandAdd:0    },
    { label:'Skyline',  name:`${co} Sky ${v}`,          costMult:1.18, demandAdd:0.01 },
    { label:'Flagship', name:`${co} ${v} of Champions`, costMult:1.4,  demandAdd:0.02 },
  ];
}
function sportTeamName(city, sport){
  // deterministic pick so the same city always gets the same team name
  let h=0; const s=(city||'')+sport.id; for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0;
  const first=(city||'City').split(/\s|-/)[0];
  return `${first} ${sport.teams[h % sport.teams.length]}`;
}
function buildInvestimatesTab(cityName) {
  const c = CITIES[cityName]; if (!c) return '';
  const inv  = (STATE.cityInvestments || {})[cityName] || {};
  const spon = (STATE.sponsorships    || {});
  const myRoutes = STATE.routes.filter(r=>r.from===cityName||r.to===cityName);
  const passiveTotal = CITY_BUILDINGS.reduce((sum, b) => {
    const level = (inv[b.id] || {}).level || 0;
    if (b.passiveIncome && level > 0) sum += b.passiveIncome * level;
    return sum;
  }, 0);
  let html = '';
  html += `<div style="display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap">
    <div class="city-stat-box" style="flex:1;min-width:100px">
      <div class="csb-l">Passive Income</div>
      <div class="csb-v" style="color:var(--profit)">+$${passiveTotal.toFixed(1)}M/mo</div>
    </div>
    <div class="city-stat-box" style="flex:1;min-width:100px">
      <div class="csb-l">Buildings</div>
      <div class="csb-v">${Object.keys(inv).filter(k=>(inv[k].level||0)>0).length} / ${CITY_BUILDINGS.length}</div>
    </div>
    <div class="city-stat-box" style="flex:1;min-width:100px">
      <div class="csb-l">Active Sponsors</div>
      <div class="csb-v">${Object.values(spon).filter(s=>s.city===cityName&&s.monthsLeft>0).length}</div>
    </div>
  </div>`;
  const ECON_REF = ECON;
  const otherCities = Object.entries(CITIES)
    .filter(([n]) => n !== cityName && !STATE.routes.some(r=>(r.from===cityName&&r.to===n)||(r.to===cityName&&r.from===n)))
    .map(([n, ct]) => {
      const dist = getDistance(cityName, n);
      const ac = AIRCRAFT['A320'] || Object.values(AIRCRAFT)[0]; // reference aircraft for forecast
      const refFare = ECON_REF.refFareBase + dist * ECON_REF.refFareDist;
      let demand = (c.pop+ct.pop)*ECON_REF.demandPop + (c.econ+ct.econ)*ECON_REF.demandEcon + (c.tourism+ct.tourism)*ECON_REF.demandTour;
      demand *= 1/(1+dist/ECON_REF.distDecay);
      demand *= 1+((c.level+ct.level)/2-3)*0.05;
      const cap = ac.seats * 3 * ECON_REF.weeksPerMonth;
      const projLoad = Math.min(100, Math.round(demand/cap*100));
      const rivals = STATE.competitors.filter(cc=>cc.regionsEntered.includes(ct.region)).length;
      const adjDemand = Math.round(demand * (1/(1+rivals*ECON_REF.rivalSplit)));
      return { name:n, ct, dist:Math.round(dist), demand:adjDemand, projLoad, refFare:Math.round(refFare), region:ct.region };
    })
    .sort((a,b) => b.demand - a.demand)
    .slice(0, 8);
  // ── Collapsible sections (chevron accordions, like Buy Aircraft) ──
  STATE._cmDemandOpen = STATE._cmDemandOpen || { forecast:true, buildings:true, sponsors:false };
  const sec = (id, icon, title, meta, inner) => {
    const open = !!STATE._cmDemandOpen[id];
    return `<div class="cm-acc">
      <div class="cm-acc-head" onclick="toggleCmDemand('${id}')">
        <span class="cm-acc-chev" id="cm-chev-${id}" style="transform:rotate(${open?90:0}deg)">›</span>
        <span style="font-size:15.8px">${icon}</span>
        <span class="cm-acc-title">${title}</span>
        <span class="cm-acc-meta">${meta}</span>
      </div>
      <div class="cm-acc-body" id="cm-acc-${id}" style="display:${open?'block':'none'}">${inner}</div>
    </div>`;
  };

  let forecastInner = '';
  if (otherCities.length > 0) {
    forecastInner += `<div style="font-size:11.3px;color:var(--muted2);margin-bottom:8px">Projected demand at 3 flights/week with a B727. Rivals already in region reduce estimate.</div>`;
    otherCities.forEach(({name, ct, dist, demand, projLoad, refFare, region}) => {
      const loadColor = projLoad >= 70 ? 'var(--profit)' : projLoad >= 45 ? 'var(--warn)' : 'var(--muted)';
      forecastInner += `<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;padding:6px 8px;background:rgba(0,0,0,0.2);border-radius:5px;font-size:11.3px">
        <div style="flex:1">
          <span style="color:var(--text);font-weight:600">${name}</span>
          <span style="color:var(--muted2);font-size:11.3px;margin-left:6px">${dist.toLocaleString()}mi · ${region}</span>
        </div>
        <div style="text-align:right;min-width:80px">
          <div style="color:${loadColor};font-weight:700">${projLoad}% load</div>
          <div style="font-size:10.7px;color:var(--muted2)">~${demand.toLocaleString()} pass/mo</div>
        </div>
        <div style="min-width:48px;text-align:right;font-size:11.3px;color:var(--muted2)">$${refFare} ref</div>
      </div>`;
    });
    forecastInner += `<div style="font-size:10.7px;color:var(--muted2)">Showing top ${otherCities.length} unserved markets by demand. Mature routes earn ~20% more than shown.</div>`;
    html += sec('forecast', '📊', 'Route Forecast', `${otherCities.length} markets`, forecastInner);
  }
  let buildingsInner = '';
  const builtCount = Object.keys(inv).filter(k=>(inv[k].level||0)>0).length;
  let _ivBest = null, _ivBestRoi = -1;
  CITY_BUILDINGS.forEach(b => {
    const lv = (inv[b.id] || {}).level || 0;
    if (lv >= b.maxLevel || !(b.passiveIncome > 0)) return;
    const cst = Math.round(b.baseCost * Math.pow(b.levelCostMult, lv));
    if (STATE.cash >= cst) { const r = b.passiveIncome * 12 / cst; if (r > _ivBestRoi) { _ivBestRoi = r; _ivBest = b.id; } }
  });
  CITY_BUILDINGS.forEach(b => {
    const bState = inv[b.id] || { level: 0 };
    const level   = bState.level || 0;
    const maxed   = level >= b.maxLevel;
    const nextCost = Math.round(b.baseCost * Math.pow(b.levelCostMult, level));
    const canAfford = STATE.cash >= nextCost;
    const levelDots = '■'.repeat(level) + '□'.repeat(b.maxLevel - level);
    const activeBenefits = [];
    if (b.demandBonus) activeBenefits.push(`+${Math.round(b.demandBonus*100*level)}% demand`);
    if (b.costSavePct) activeBenefits.push(`-${Math.round(b.costSavePct*100*level)}% costs`);
    if (b.passiveIncome) activeBenefits.push(`+$${(b.passiveIncome*level).toFixed(1)}M/mo`);
    const dInc = b.passiveIncome || 0, dDem = b.demandBonus || 0, dCost = b.costSavePct || 0;
    const payback = dInc > 0 ? Math.ceil(nextCost / dInc) : null;
    const roi = dInc > 0 ? Math.round(dInc * 12 / nextCost * 100) : null;
    const isBest = b.id === _ivBest;
    const chips = [];
    if (dInc > 0) {
      chips.push(['Income', `+$${dInc.toFixed(1)}M/mo`, 'var(--profit)']);
      chips.push(['ROI / yr', `${roi}%`, 'var(--accent2)']);
      chips.push(['Payback', `${payback}mo`, 'var(--accent)']);
    }
    if (dDem > 0)  chips.push(['Demand', `+${Math.round(dDem*100)}%`, 'var(--accent)']);
    if (dCost > 0) chips.push(['Costs', `-${Math.round(dCost*100)}%`, 'var(--profit)']);
    const chipHtml = chips.slice(0,4).map(([l,v,c]) => `<div class="iv-st"><div class="iv-st-l">${l}</div><div class="iv-st-v" style="color:${c}">${v}</div></div>`).join('');
    const pill = dInc > 0
      ? `<span class="iv-risk iv-r-low">Low risk</span>`
      : `<span class="iv-risk iv-r-strat">Strategic</span>`;
    buildingsInner += `<div class="iv-card${level>0?' iv-built':''}${isBest?' iv-best':''}">
      <div class="iv-hd">
        <span class="iv-ic">${b.icon}</span>
        <div style="flex:1;min-width:0">
          <div><span class="iv-nm">${b.name}</span><span class="iv-lv">${levelDots} Lv${level}/${b.maxLevel}</span>${isBest?'<span class="iv-tag">BEST ROI</span>':''}</div>
          <div class="iv-desc">${b.desc}</div>
        </div>
        ${maxed ? '' : `<span class="iv-cost">$${nextCost}M</span>`}
      </div>
      ${level > 0 ? `<div class="iv-active">✓ Active: ${activeBenefits.join(' · ')}</div>` : ''}
      ${maxed
        ? `<div style="font-size:11.3px;color:var(--accent2);font-weight:600;margin-top:6px">★ MAXED OUT</div>`
        : `<div class="iv-grid">${chipHtml}</div>
           <div class="iv-foot">
             ${pill}
             <button class="action-btn${level>0?' success':''} iv-btn"
               style="padding:6px 10px;font-size:11.3px;${!canAfford?'opacity:0.5':''}"
               onclick="${canAfford?`buyBuilding('${cityName}','${b.id}',${nextCost})`:`showFlash('Need $${nextCost}M to build')`}"
               ${!canAfford?'title="Not enough cash"':''}>
               ${level===0?'Build':'Upgrade'} — $${nextCost}M
             </button>
           </div>`}
    </div>`;
  });
  html += sec('buildings', '🏗', 'Buildings & Infrastructure', `${builtCount}/${CITY_BUILDINGS.length} built`, buildingsInner);
  let sponsorsInner = '';
  const activeSponsorCount = Object.values(spon).filter(s=>s.city===cityName&&s.monthsLeft>0).length;
  CITY_SPONSORSHIPS.forEach(s => {
    const active = Object.entries(spon).find(([k,v]) => k===`${cityName}_${s.id}` && v.monthsLeft>0);
    const canAfford = STATE.cash >= s.baseCost;
    const ret = s.monthlyReturn || 0, dem = s.demandBonus || 0, dur = s.duration;
    const net = ret * dur - s.baseCost;
    const chips = [];
    if (ret > 0) {
      chips.push(['Return', `+$${ret}M/mo`, 'var(--profit)']);
      chips.push(['Net / term', `${net>=0?'+':'-'}$${Math.abs(net).toFixed(1)}M`, net>=0?'var(--profit)':'var(--loss)']);
      chips.push(['Payback', `${Math.ceil(s.baseCost/ret)}mo`, 'var(--accent)']);
    }
    if (dem > 0) chips.push(['Demand', `+${Math.round(dem*100)}%`, 'var(--accent)']);
    const chipHtml = chips.slice(0,4).map(([l,v,cc]) => `<div class="iv-st"><div class="iv-st-l">${l}</div><div class="iv-st-v" style="color:${cc}">${v}</div></div>`).join('');
    const pill = (ret > 0 && net >= 0)
      ? `<span class="iv-risk iv-r-low">Profitable</span>`
      : `<span class="iv-risk iv-r-strat">Demand play</span>`;
    sponsorsInner += `<div class="iv-card${active?' iv-built':''}">
      <div class="iv-hd">
        <span class="iv-ic">${s.icon}</span>
        <div style="flex:1;min-width:0">
          <div><span class="iv-nm">${s.name}</span><span class="iv-lv">${dur}-mo term</span></div>
          <div class="iv-desc">${s.desc}</div>
        </div>
        ${active ? '' : `<span class="iv-cost">$${s.baseCost}M</span>`}
      </div>
      ${active
        ? `<div class="iv-active">✓ Live — ${active[1].monthsLeft} month${active[1].monthsLeft!==1?'s':''} remaining</div>`
        : `<div class="iv-grid">${chipHtml}</div>
           <div class="iv-foot">
             ${pill}
             <button class="action-btn${canAfford?' gold':''} iv-btn"
               style="padding:6px 10px;font-size:11.3px;${!canAfford?'opacity:0.5':''}"
               onclick="${canAfford?`buySponsorship('${cityName}','${s.id}',${s.baseCost},${s.duration},${s.monthlyReturn},${s.demandBonus})`:`showFlash('Need $${s.baseCost}M to sponsor')`}"
               ${!canAfford?'title="Not enough cash"':''}>
               Sponsor — $${s.baseCost}M
             </button>
           </div>`}
    </div>`;
  });
  html += sec('sponsors', '🤝', 'Sponsorships & Activities', activeSponsorCount?`${activeSponsorCount} active`:`${CITY_SPONSORSHIPS.length} available`, sponsorsInner);
  return html;
}
function toggleCmDemand(id){
  STATE._cmDemandOpen = STATE._cmDemandOpen || {};
  STATE._cmDemandOpen[id] = !STATE._cmDemandOpen[id];
  const body = document.getElementById('cm-acc-'+id);
  const chev = document.getElementById('cm-chev-'+id);
  if (body) body.style.display = STATE._cmDemandOpen[id] ? 'block' : 'none';
  if (chev) chev.style.transform = STATE._cmDemandOpen[id] ? 'rotate(90deg)' : 'rotate(0deg)';
}
function buyBuilding(city, buildingId, cost) {
  if (STATE.cash < cost) { showFlash('⚠ Not enough cash'); return; }
  STATE.cash -= cost;
  STATE.cityInvestments = STATE.cityInvestments || {};
  STATE.cityInvestments[city] = STATE.cityInvestments[city] || {};
  const b = STATE.cityInvestments[city][buildingId] || { level: 0 };
  b.level = (b.level || 0) + 1;
  b.purchasedMonth = (STATE._absMonth || 0);
  STATE.cityInvestments[city][buildingId] = b;
  const def = CITY_BUILDINGS.find(x => x.id === buildingId);
  showFlash(`✓ ${def ? def.name : buildingId} Lv${b.level} built at ${city}`);
  addEvent('good', `🏗 ${city}: ${def ? def.name : buildingId} upgraded to Level ${b.level}.`);
  updateUI();
  const el = document.getElementById('cm-demand');
  if (el && el.style.display !== 'none') el.innerHTML = buildInvestimatesTab(city);
}
function buySponsorship(city, sponsorId, cost, duration, monthlyReturn, demandBonus) {
  if (STATE.cash < cost) { showFlash('⚠ Not enough cash'); return; }
  STATE.cash -= cost;
  STATE.sponsorships = STATE.sponsorships || {};
  const key = `${city}_${sponsorId}`;
  const def = CITY_SPONSORSHIPS.find(x => x.id === sponsorId);
  STATE.sponsorships[key] = { city, id: sponsorId, name: def ? def.name : sponsorId, icon: def ? def.icon : '🎯', monthsLeft: duration, monthlyReturn, demandBonus };
  showFlash(`✓ ${def ? def.name : sponsorId} sponsored at ${city} for ${duration} months`);
  addEvent('good', `🤝 ${city}: Sponsorship — ${def ? def.name : sponsorId} active for ${duration} months.`);
  updateUI();
  const el = document.getElementById('cm-demand');
  if (el && el.style.display !== 'none') el.innerHTML = buildInvestimatesTab(city);
}
let _sportsPick = null;
