function onArenaNameInput(v){ _sportsPick.arenaName = v; const p=document.getElementById('arena-preview-name'); if(p) p.textContent = v.trim() || '—'; }
function onTeamNameInput(v){ _sportsPick.teamName = v; const p=document.getElementById('arena-preview-team'); if(p) p.textContent = v.trim() || '—'; }
