  s+=`<rect x="-32" y="14" width="64" height="3" fill="#4a4030" opacity=".6"/>`;
  s+=`<path d="M-2,14 L2,18 L-3,21 L3,25 L-1,28" stroke="#15110c" stroke-width="2.4" fill="none"/>`;
  s+=`<path d="M-2,14 L2,18 L-3,21 L3,25 L-1,28" stroke="#ff8a2a" stroke-width="1" fill="none" opacity=".45" class="wx-glow"/>`;
  s+=`<path d="M0,17 L-9,15 L-14,18" stroke="#1c160f" stroke-width="1.4" fill="none"/>`;
