  for(let i=0;i<6;i++){const x=_wxRnd(-20,20).toFixed(1),dl=_wxRnd(0,2).toFixed(2);s+=`<ellipse cx="${x}" cy="14" rx="5" ry="3" fill="#9a8c70" opacity=".4" class="ash-rise" style="animation-delay:${dl}s"/>`;}
  return s;
