// ═══════════════════════════════════════════════════════════════════════════
function execTier(role) {
  const e = (STATE.board||{})[role];
  if (!e) return null;
  return (BOARD_ROLES[role].tiers).find(t => t.tier === e.tier) || null;
}
function execBonus(role, key) {
  const t = execTier(role);
  if (!t) return 0;
  const base = t[key] || 0;
  // Apply personality multiplier to numeric bonuses (not salary/tier/title strings)
  if (typeof base === 'number' && key !== 'tier' && key !== 'salary' && key !== 'hire') {
    const p = getPersonality(role);
    return base * (p.effectMult || 1);
  }
  return base;
}
// COO load-boost eases off as the network grows so a sprawling map doesn't
// compound a flat demand multiplier on every route. floor=1 disables the taper.
function cooLoadBoost() {
  const base = execBonus('coo', 'loadBoost');
  if (base <= 0) return 0;
  const n = (STATE.routes || []).length;
  const floor = (ECON.cooScaleFloor == null ? 1 : ECON.cooScaleFloor);
  const scale = (ECON.cooScaleRoutes || 28);
  const taper = floor + (1 - floor) * (1 / (1 + n / scale));
  return base * taper;
}
function boardSalary() {
  return ['cfo','coo','strategy'].reduce((s,r) => {
    const t = execTier(r);
    if (!t) return s;
    const p = getPersonality(r);
    return s + t.salary * (p.salaryMult || 1);
  }, 0);
}
function hireExec(role, tier) {
  const t = (BOARD_ROLES[role].tiers).find(x => x.tier === tier);
  if (!t) return;
  if (STATE.cash < t.hire) { showFlash('Not enough cash for signing bonus'); return; }
  STATE.cash -= t.hire;
  if (!STATE.board) STATE.board = { cfo:null, coo:null, strategy:null };
  const name = (STATE.board[role] && STATE.board[role].name) || _execName();
  // Keep personality if re-hiring same role (promotion), assign new one otherwise
  const existingPersonality = STATE.board[role] && STATE.board[role].personalityId;
  const personality = existingPersonality ? (EXEC_PERSONALITIES[role]||[]).find(p=>p.id===existingPersonality) : _execPersonality(role);
  const personalityId = personality ? personality.id : 'steady';
  STATE.board[role] = { tier, name, personalityId };
  const pLabel = personality ? ` (${personality.icon} ${personality.label})` : '';
  const salaryEff = t.salary * ((personality||{}).salaryMult||1);
  addEvent('good', `${BOARD_ROLES[role].icon} Hired ${name} as ${t.title}${pLabel} (−$${t.hire}M signing, $${salaryEff.toFixed(1)}M/mo).`);
  showFlash(`${BOARD_ROLES[role].icon} ${t.title} hired`);
  showBoardMeeting();
}
function fireExec(role) {
  if (!STATE.board || !STATE.board[role]) return;
  const nm = STATE.board[role].name;
  STATE.board[role] = null;
  addEvent('neutral', `Dismissed ${nm} from the ${BOARD_ROLES[role].short} role.`);
  showBoardMeeting();
}
